import 'dart:io';

import 'package:test/test.dart';

/// Enforces the cross-feature seam requirements such as P-RF10's FR-009
/// establish: a `presentation/bloc/` file may import another feature's
/// `domain/usecases/` or `domain/entities/` classes (the sanctioned seam),
/// but MUST NOT import another feature's `data/` layer class or its
/// `domain/repositories/` interface directly. Unlike
/// `no_bloc_imports_bloc_test.dart` (bloc-to-bloc only) and
/// `domain_purity_test.dart` (domain/ folder only, same-feature layer
/// purity), this is the one check that can actually catch a bloc reaching
/// past a usecase into another feature's repository or data source.
void main() {
  test(
    "no presentation/bloc/ file imports another feature's data/ or domain/repositories/ class",
    () {
      final blocFiles = Directory('lib')
          .listSync(recursive: true)
          .whereType<File>()
          .where((f) => f.path.endsWith('.dart'))
          .where((f) => f.path.contains(
              '${Platform.pathSeparator}presentation${Platform.pathSeparator}bloc${Platform.pathSeparator}'))
          .toList();

      expect(blocFiles, isNotEmpty,
          reason: 'expected to find presentation/bloc/ files under lib/');

      final importPattern = RegExp(r'''^import\s+['"]([^'"]+)['"]''');
      final violations = <String>[];

      for (final file in blocFiles) {
        final ownFeature = _featureOf(file.path);
        for (final line in file.readAsLinesSync()) {
          final match = importPattern.firstMatch(line.trim());
          if (match == null) continue;
          final target = match.group(1)!;
          final targetFeature = _featureOfImport(target);
          if (targetFeature == null || targetFeature == ownFeature) continue;

          final isData = target.contains('/data/');
          final isRepositoryInterface = target.contains('/domain/repositories/');
          if (isData || isRepositoryInterface) {
            violations.add(
                '${file.path}: imports another feature\'s ${isData ? 'data' : 'repository'} class ($target)');
          }
        }
      }

      expect(violations, isEmpty, reason: violations.join('\n'));
    },
  );
}

String? _featureOf(String path) {
  final segments = path.split(Platform.pathSeparator);
  final index = segments.indexOf('features');
  if (index == -1 || index + 1 >= segments.length) return null;
  return segments[index + 1];
}

String? _featureOfImport(String importPath) {
  final segments = importPath.split('/');
  final index = segments.indexOf('features');
  if (index == -1 || index + 1 >= segments.length) return null;
  return segments[index + 1];
}

